highest_priced_car_sold_on_inventory_out_day = Sales.WHERE(
    HAS(car.inventory_snapshots.WHERE((is_in_inventory == False) & (snapshot_date == sale_date))) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    car_make=car.make,
    car_model=car.model,
    sale_price=sale_price
)
